        <p class="addresssender">edevis GmbH | Wilhelm-Haas-Str. 2 | D-70771 Leinfelden-Echterdingen</p>
    <strong>{{ doc.customer_name }}</strong><br/>
	{% if doc.address_display %}
	    {{ doc.address_display }}
	{% endif %}

	<br/>

	</td>
	<td style="width:40%">
		<table class="dense" style="width: 100%">
			<tr><td>{{ _("Customer No.") }}:</td><td style="text-align: right;">{{ doc.customer }}</td></tr>
			<tr><td>{{ _("Customer VAT-Id") }}:</td><td style="text-align: right;">{{ frappe.db.get_value("Customer", doc.customer, "tax_id") or "" }}</td></tr>
			<tr><td>{{ _("Supp.No. ref. Cust.No.") }}:</td><td style="text-align: right;">{{ frappe.db.get_value("Customer", doc.customer, "supp_no_ref_cust_no") or "" }}</td></tr>			
			<tr><td>{{ _("Order No.") }}:</td><td style="text-align: right;">{{ doc.po_no or "" }}</td></tr>
			<tr><td>{{ _("Processed by") }}:</td><td style="text-align: right;">{{ frappe.get_fullname(doc.modified_by) or "" }}</td></tr>
			<tr><td>{{ _("Project No.") }}:</td><td style="text-align: right;">{{ doc.project or "" }}</td></tr>			
			<tr><td>{{ _("Date") }}:</td><td style="text-align: right;">{{ frappe.utils.formatdate(doc.posting_date, "dd.MM.yyyy") }}</td></tr>
		</table>
	</td>	
</tr>    
</table>

<!-- HEADER -->
{% if doc.docstatus == 0 %}
<H2 style="text-align: center;">
    --- ENTWURF ---
</H2>
{% endif %}

{% set ns.Columns = 4 %}

<div>
    <h5>{{ _("Delivery Note") }} <span style="font-weight: bold;">{{ doc.name }}</span></h5>
</div>

<div style="margin-bottom: 2em;">
    {{ doc.delivery_note_note or "" }}
</div>

<div>
    {% if doc.header_text %}
        {{ doc.header_text }}
    {% endif %}
</div>
<!-- PRICE TABLE -->
<table class=" table-sm pricetable" >
	<thead>
		<tr class="">
			<th width="5%">{{ _("Item Pos") }}</th>
			<th width="10%">{{ _("Item No") }}</th>
			<th width="25%">{{ _("Description") }}</th>
			<th width="5%" class="text-right">{{ _("Qty") }}</th>
			<th width="5%" class="text-right">{{ _("Weight") }}</th>
		</tr>
	</thead>
	<tbody>
	    <!-- add parent relationship info to the quotation_items => support hierarchical section headers -->
		{%- for item in structurize_quoteitem(doc) -%}
            <!-- format with separator lines if element is first order position (POS1), else without (POS 1.1) -->
            {% set ns.tableLine = "tableLine" if not item.parent_item else "" %}
            <!-- format bold and with separator lines for section headers -->
            {% set ns.tableLine = "tableLine sectionHeader" if quoteitem_is_header(item) else ns.tableLine %}

    		<tr class="quoteitems {{ ns.tableLine }}">
		        <td class="">{{ item.position }}</td>

			    <td class="">
        		{{ item.item_code if item.item_group != "Format Elemente" else ""}}


			    <td class="">
			        <p>{{ _(item.item_name)}}</p>

		 			{% if not print_settings.compact_item_print and item.item_group != "Format Elemente" %}
                    <p>{{ _(item.description)}}</p>    
                    {%- endif -%}
        		    {% if item.serial_no %}
        		    {{ _("Serial No") }}: {{ item.serial_no.replace('\n', ', ') if item.serial_no else "" }}
        		    {% endif %}
        		    {%- set customer_ref_code = frappe.db.get_value("Item Customer Detail", {"parent": item.item_code}, "ref_code") -%}
                        {% if customer_ref_code %}
                            {{ _("Ref. Code") }}: {{ customer_ref_code }}
                        {% endif %}
        		    <!--Display of country of origin and custom tarif number-->
                    {% set country_of_origin = frappe.db.get_value("Item", item.item_code, "country_of_origin") %}
                    {% set tariff_number = frappe.db.get_value("Item", item.item_code, "customs_tariff_number") %}
                    {% set dual_use_export_item_number = frappe.db.get_value("Item", item.item_code, "custom_dual_use_export_item_number") %}
                    {% if country_of_origin or tariff_number or dual_use_export_item_number %}
                    <p>
                      {% if country_of_origin %}{{ _("Country of Origin") }}: {{ _(country_of_origin) }}{% endif %}
                      {% if country_of_origin and (tariff_number or dual_use_export_item_number) %},&nbsp;{% endif %}
                      {% if tariff_number %}{{ _("Customs Tariff Number") }}: {{ _(tariff_number) }}{% endif %}
                      {% if tariff_number and dual_use_export_item_number %}&nbsp;{% endif %}<br>
                      {% if dual_use_export_item_number %}{{ _("ECCN / EU Dual-Use Regulation 2021/821") }}: {{ _(dual_use_export_item_number) }}{% endif %}
                    </p>
                    {% endif %}

    			</td>
    			{% if doc.flags.print_settings.print_uom_after_quantity %}
    			    <td class=" text-right">{{ item.qty if item.qty != 0 else "" }} {{ _(item.uom) }}</td>
    			{% else %}
    			    <td class=" text-right">{{ _(item.uom) if item.qty != 0 else "" }} {{ item.qty if item.qty != 0 else "" }}</td>
    			{% endif %}

    			<td class=" text-right">{{ _(item.total_weight) if item.total_weight else "" }} {{ _(item.weight_uom) if item.weight_uom else "Kg"}}</td>

    		</tr>

		{%- endfor -%}

		{% set ns.tableLine = "tableLine" %}

	</tbody>
</table>


